CREATE SCHEMA `tienda_vega`;


CREATE TABLE `tienda_vega`.`clientes` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `correo` VARCHAR(100) NOT NULL,
  `clave` VARCHAR(200) NOT NULL,
  `nombres` VARCHAR(60) NOT NULL,
  `apellidos` VARCHAR(60) NOT NULL,
  `estado` INT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `correo_UNIQUE` (`correo` ASC) VISIBLE);

CREATE TABLE `tienda_vega`.`ubigeo` (
  `cod_ubigeo` VARCHAR(6) NOT NULL,
  `txt_ubigeo` VARCHAR(100) NOT NULL,
  `cod_ubigeo_padre` VARCHAR(6) NOT NULL,
  PRIMARY KEY (`cod_ubigeo`));



CREATE TABLE `tienda_vega`.`departamento` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`));



CREATE TABLE `tienda_vega`.`grupo` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `departamento_id` INT NOT NULL,
  `nombre` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_grupo_departamento_idx` (`departamento_id` ASC) VISIBLE,
  CONSTRAINT `fk_grupo_departamento`
    FOREIGN KEY (`departamento_id`)
    REFERENCES `tienda_vega`.`departamento` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);




















CREATE TABLE `tienda_vega`.`categoria` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `grupo_id` INT NOT NULL,
  `nombre` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_categoria_grupo_idx` (`grupo_id` ASC) VISIBLE,
  CONSTRAINT `fk_categoria_grupo`
    FOREIGN KEY (`grupo_id`)
    REFERENCES `tienda_vega`.`grupo` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);


CREATE TABLE `tienda_vega`.`marcas` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(100) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `nombre_UNIQUE` (`nombre` ASC) VISIBLE);



CREATE TABLE `tienda_vega`.`productos` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `categoria_id` INT NOT NULL,
  `marca_id` INT NOT NULL,
  `sku` VARCHAR(50) NOT NULL,
  `descripcion` VARCHAR(100) NOT NULL,
  `precio_lista` DECIMAL(11,2) NOT NULL,
  `precio_online` DECIMAL(11,2) NOT NULL,
  `stock` INT NOT NULL,
  PRIMARY KEY (`id`));
  
ALTER TABLE `tienda_vega`.`productos` 
ADD INDEX `fk_productos_marca_idx` (`marca_id` ASC) VISIBLE,
ADD INDEX `fk_productos_categoria_idx` (`categoria_id` ASC) VISIBLE;
;
ALTER TABLE `tienda_vega`.`productos` 
ADD CONSTRAINT `fk_productos_marca`
  FOREIGN KEY (`marca_id`)
  REFERENCES `tienda_vega`.`marcas` (`id`)
  ON DELETE NO ACTION
  ON UPDATE NO ACTION,
ADD CONSTRAINT `fk_productos_categoria`
  FOREIGN KEY (`categoria_id`)
  REFERENCES `tienda_vega`.`categoria` (`id`)
  ON DELETE NO ACTION
  ON UPDATE NO ACTION;


ALTER TABLE `tienda_vega`.`productos` 
ADD COLUMN `ruta_img` VARCHAR(250) NOT NULL DEFAULT 'sin imagen' AFTER `stock`;


CREATE TABLE `tienda_vega`.`tiendas` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `nombre` VARCHAR(150) NOT NULL,
  `direccion` VARCHAR(150) NOT NULL,
  `cod_ubigeo` VARCHAR(6) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_tiendas_ubigeo_idx` (`cod_ubigeo` ASC) VISIBLE,
  CONSTRAINT `fk_tiendas_ubigeo`
    FOREIGN KEY (`cod_ubigeo`)
    REFERENCES `tienda_vega`.`ubigeo` (`cod_ubigeo`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);



CREATE TABLE `tienda_vega`.`cliente_direcciones` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `cliente_id` INT NOT NULL,
  `direccion` VARCHAR(150) NOT NULL,
  `cod_ubigeo` VARCHAR(6) NOT NULL,
  `estado` INT NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_direccion_cliente_idx` (`cliente_id` ASC) VISIBLE,
  INDEX `fk_direccion_ubigeo_idx` (`cod_ubigeo` ASC) VISIBLE,
  CONSTRAINT `fk_direccion_cliente`
    FOREIGN KEY (`cliente_id`)
    REFERENCES `tienda_vega`.`clientes` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_direccion_ubigeo`
    FOREIGN KEY (`cod_ubigeo`)
    REFERENCES `tienda_vega`.`ubigeo` (`cod_ubigeo`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);

CREATE TABLE `tienda_vega`.`usuario` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `nombres` VARCHAR(100) NOT NULL,
  `apellidos` VARCHAR(100) NOT NULL,
  `usuario` VARCHAR(50) NOT NULL,
  `clave` VARCHAR(50) NOT NULL,
  `estado` INT NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE INDEX `usuario_UNIQUE` (`usuario` ASC) VISIBLE);

ALTER TABLE `tienda_vega`.`departamento` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `nombre`;

ALTER TABLE `tienda_vega`.`grupo` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `nombre`;

ALTER TABLE `tienda_vega`.`categoria` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `nombre`;

ALTER TABLE `tienda_vega`.`marcas` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `nombre`;

ALTER TABLE `tienda_vega`.`productos` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `ruta_img`;

CREATE TABLE `tienda_vega`.`roles` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `descripcion` VARCHAR(60) NOT NULL,
  `estado` INT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`));


ALTER TABLE `tienda_vega`.`usuario` 
ADD COLUMN `rol_id` INT NOT NULL DEFAULT 4 AFTER `estado`,
ADD INDEX `fk_usuario_roles_idx` (`rol_id` ASC) VISIBLE;
;
ALTER TABLE `tienda_vega`.`usuario` 
ADD CONSTRAINT `fk_usuario_roles`
  FOREIGN KEY (`rol_id`)
  REFERENCES `tienda_vega`.`roles` (`id`)
  ON DELETE NO ACTION
  ON UPDATE NO ACTION;

ALTER TABLE `tienda_vega`.`usuario` 
CHANGE COLUMN `clave` `clave` VARCHAR(200) NOT NULL ;

ALTER TABLE `tienda_vega`.`usuario` 
CHANGE COLUMN `estado` `estado` INT NOT NULL DEFAULT 1 ;


ALTER TABLE `tienda_vega`.`tiendas` 
ADD COLUMN `estado` INT NOT NULL DEFAULT 1 AFTER `cod_ubigeo`;

CREATE TABLE `tienda_vega`.`almacen` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `tienda_id` INT NOT NULL,
  `producto_id` INT NOT NULL,
  `fecha_ingreso` DATETIME NOT NULL,
  `cantidad` INT NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_almacen_tienda_idx` (`tienda_id` ASC) VISIBLE,
  INDEX `fk_almacen_producto_idx` (`producto_id` ASC) VISIBLE,
  CONSTRAINT `fk_almacen_tienda`
    FOREIGN KEY (`tienda_id`)
    REFERENCES `tienda_vega`.`tiendas` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_almacen_producto`
    FOREIGN KEY (`producto_id`)
    REFERENCES `tienda_vega`.`productos` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);


ALTER TABLE `tienda_vega`.`productos` 
ADD COLUMN `slug` VARCHAR(150) NOT NULL DEFAULT '' AFTER `ruta_img`,
ADD COLUMN `unidad` VARCHAR(45) NOT NULL DEFAULT 'Unidad' AFTER `slug`,
ADD COLUMN `color_placeholder` VARCHAR(45) NOT NULL DEFAULT '#F4F6F8' AFTER `unidad`,
ADD COLUMN `descripcion_larga` VARCHAR(500) NOT NULL DEFAULT '' AFTER `color_placeholder`,
ADD COLUMN `oferta` INT NOT NULL DEFAULT 0 AFTER `descripcion_larga`,
ADD COLUMN `destacado` INT NOT NULL DEFAULT 0 AFTER `oferta`,
ADD COLUMN `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP AFTER `destacado`,
CHANGE COLUMN `ruta_img` `ruta_img` VARCHAR(500) NOT NULL DEFAULT 'sin imagen' ;




ALTER TABLE `tienda_vega`.`tiendas` 
ADD COLUMN `horario` VARCHAR(100) NOT NULL DEFAULT 'Lun-Dom 7:00-22:00' AFTER `cod_ubigeo`,
ADD COLUMN `telefono` VARCHAR(20) NOT NULL DEFAULT '999999999' AFTER `horario`,
ADD COLUMN `imagen_url` VARCHAR(255) NOT NULL DEFAULT '' AFTER `telefono`,
ADD COLUMN `lat` DECIMAL(10,7) NOT NULL DEFAULT -12.0954000 AFTER `imagen_url`,
ADD COLUMN `lng` DECIMAL(10,7) NOT NULL DEFAULT -77.0365000 AFTER `lat`;


CREATE TABLE `tienda_vega`.`pedidos` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `cliente_id` INT NOT NULL,
  `tienda_id` INT NOT NULL,
  `total` DECIMAL(11,2) NOT NULL,
  `estado` ENUM('PENDIENTE_PAGO', 'PENDIENTE_DESPACHO', 'PENDIENTE_ENTREGA', 'ENTREGADO') NOT NULL DEFAULT 'PENDIENTE_PAGO',
  `fecha_creacion` DATETIME NOT NULL,
  `fecha_pago` DATETIME NULL,
  `fecha_despacho` DATETIME NULL,
  `fecha_recojo` DATETIME NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_pedido_cliente_idx` (`cliente_id` ASC) VISIBLE,
  INDEX `fk_pedido_tienda_idx` (`tienda_id` ASC) VISIBLE,
  CONSTRAINT `fk_pedido_cliente`
    FOREIGN KEY (`cliente_id`)
    REFERENCES `tienda_vega`.`clientes` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_pedido_tienda`
    FOREIGN KEY (`tienda_id`)
    REFERENCES `tienda_vega`.`tiendas` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);

CREATE TABLE `tienda_vega`.`pedidos_detalles` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `pedido_id` INT NOT NULL,
  `producto_id` INT NOT NULL,
  `cantidad` INT NOT NULL,
  `subtotal` DECIMAL(11,2) NOT NULL,
  PRIMARY KEY (`id`),
  INDEX `fk_pdetalles_pedido_idx` (`pedido_id` ASC) VISIBLE,
  INDEX `fk_pdetalles_producto_idx` (`producto_id` ASC) VISIBLE,
  CONSTRAINT `fk_pdetalles_pedido`
    FOREIGN KEY (`pedido_id`)
    REFERENCES `tienda_vega`.`pedidos` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_pdetalles_producto`
    FOREIGN KEY (`producto_id`)
    REFERENCES `tienda_vega`.`productos` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);

CREATE TABLE `tienda_vega`.`reclamos` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `cliente_id` INT NOT NULL,
  `fecha_creacion` DATETIME NOT NULL,
  `fecha_atencion` DATETIME NULL,
  `pedido_id` INT NOT NULL,
  `comentario` TEXT NOT NULL,
  `comentario_respuesta` TEXT NULL,
  `estado` ENUM('PENDIENTE', 'ATENDIDO') NOT NULL DEFAULT 'PENDIENTE',
  PRIMARY KEY (`id`),
  INDEX `fk_reclamo_cliente_idx` (`cliente_id` ASC) VISIBLE,
  INDEX `fk_reclamo_pedido_idx` (`pedido_id` ASC) VISIBLE,
  CONSTRAINT `fk_reclamo_cliente`
    FOREIGN KEY (`cliente_id`)
    REFERENCES `tienda_vega`.`clientes` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_reclamo_pedido`
    FOREIGN KEY (`pedido_id`)
    REFERENCES `tienda_vega`.`pedidos` (`id`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION);



CREATE TABLE `tienda_vega`.`tipo_pago` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `descripcion` VARCHAR(45) NOT NULL,
  `estado` INT NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`));


ALTER TABLE `tienda_vega`.`pedidos` 
ADD COLUMN `tipo_pago` INT NOT NULL DEFAULT 1 AFTER `fecha_recojo`,
ADD INDEX `fk_pedido_tipopago_idx` (`tipo_pago` ASC) VISIBLE;
;
ALTER TABLE `tienda_vega`.`pedidos` 
ADD CONSTRAINT `fk_pedido_tipopago`
  FOREIGN KEY (`tipo_pago`)
  REFERENCES `tienda_vega`.`tipo_pago` (`id`)
  ON DELETE NO ACTION
  ON UPDATE NO ACTION;


